bool CutScene::CanZombieGoInGridSpot(ZombieType theZombieType, int theGridX, int theGridY, bool (*theZombieGrid)[5])
{
    if (theZombieGrid[theGridX][theGridY])
        return false;

    if (Is2x2Zombie(theZombieType))
    {
        // A 2x2 preview needs the spot up and to the left of it as well.
        if (theGridY == 0 || theGridX == 0)
            return false;
        if (theZombieGrid[theGridX - 1][theGridY] || theZombieGrid[theGridX][theGridY - 1] ||
            theZombieGrid[theGridX - 1][theGridY - 1])
            return false;
    }

    if (theGridX == 4 && theGridY == 0)
        return false;
    if (theZombieType == ZOMBIE_ZAMBONI)
        return false;
    if (theGridX == 0 && mBoard->StageHasPool())
        return false;
    if (mBoard->StageHasRoof() && theGridX == 0 && theGridY == 0)
        return false;
    if (theGridX == 4 && mBoard->StageHasFog() && theZombieType == ZOMBIE_BALLOON)
        return false;

    // The wide zombies need one free column in front of them.
    if (Is2x2Zombie(theZombieType) || theZombieType == ZOMBIE_ZAMBONI || theZombieType == ZOMBIE_BOBSLED ||
        theZombieType == ZOMBIE_POLEVAULTER)
    {
        if (theGridX == 0 || (theGridX == 1 && mBoard->StageHasPool()))
            return false;
        if (theGridX == 1 && theGridY == 0)
            return false;
    }

    return true;
}

