// CutScene::PlaceStreetZombies(void)
// @0017732C  578 bytes
// ==========================================================================
void CutScene::PlaceStreetZombies()
{
    if (mPlacedZombies)
        return;

    mPlacedZombies = true;

    if (mApp->IsFinalBossLevel() || mApp->IsScaryPotterLevel() || mApp->IsIZombieLevel() ||
        mApp->IsWhackAZombieLevel() || mApp->IsWallnutBowlingLevel())
        return;

    bool aZombieGrid[5][5] = {{false}};
    int aZombieTypeCount[NUM_ZOMBIE_TYPES] = {0};

    // Tally the previewable zombies in the wave list. The flag zombie is never
    // previewed, the yeti only on a stormy night, the bobsled only in Bobsled
    // Bonanza, and the bungee and the bobsled are capped at one each.
    int aTotalZombieCount = 0;
    for (int aWave = 0; aWave < mBoard->mNumWaves; aWave++)
    {
        for (int aZombieIndex = 0; aZombieIndex < MAX_ZOMBIES_IN_WAVE; aZombieIndex++)
        {
            ZombieType aZombieType = mBoard->mZombiesInWave[aWave][aZombieIndex];
            if (aZombieType == ZOMBIE_INVALID)
                break;
            if (aZombieType == ZOMBIE_FLAG)
                continue;
            if (aZombieType == ZOMBIE_YETI && !mApp->IsStormyNightLevel())
                continue;
            if (aZombieType == ZOMBIE_BOBSLED && mApp->mGameMode != GAMEMODE_CHALLENGE_BOBSLED_BONANZA)
                continue;

            aTotalZombieCount++;
            aZombieTypeCount[aZombieType]++;
            if (aZombieType == ZOMBIE_BUNGEE || aZombieType == ZOMBIE_BOBSLED)
                aZombieTypeCount[aZombieType] = 1;
        }
    }

    // Last Stand previews at least one of every zombie type the level allows.
    if (mApp->mGameMode == GAMEMODE_CHALLENGE_LAST_STAND)
    {
        for (int aZombieType = 0; aZombieType < NUM_ZOMBIE_TYPES; aZombieType++)
        {
            if (aZombieType != ZOMBIE_YETI && mBoard->mZombieAllowed[aZombieType])
                aZombieTypeCount[aZombieType] = std::max(aZombieTypeCount[aZombieType], 1);
        }
    }
    if (mBoard->StageHasPool())
        aZombieTypeCount[ZOMBIE_DUCKY_TUBE] = 1;

    int aPreviewCapacity;
    if (mApp->IsLittleTroubleLevel())
        aPreviewCapacity = 15;
    else if (mApp->IsStormyNightLevel() && mApp->IsAdventureMode())
        aPreviewCapacity = 18;
    else
        aPreviewCapacity = mApp->IsMiniBossLevel() ? 18 : 10;

    // The 2x2 zombies and the zamboni take their spots first, so that the
    // smaller zombies can be packed around them.
    for (int aZombieType = 0; aZombieType < NUM_ZOMBIE_TYPES; aZombieType++)
    {
        if (aZombieTypeCount[aZombieType] != 0 &&
            (Is2x2Zombie((ZombieType)aZombieType) || aZombieType == ZOMBIE_ZAMBONI))
        {
            FindAndPlaceZombie((ZombieType)aZombieType, aZombieGrid);
        }
    }

    for (int aZombieType = 0; aZombieType < NUM_ZOMBIE_TYPES; aZombieType++)
    {
        int aZombieNumInWave = aZombieTypeCount[aZombieType];
        if (aZombieNumInWave == 0 || Is2x2Zombie((ZombieType)aZombieType) || aZombieType == ZOMBIE_ZAMBONI)
            continue;

        int aZombiePreviewNum = aZombieNumInWave * aPreviewCapacity / aTotalZombieCount;
        if (aZombiePreviewNum < 1)
            aZombiePreviewNum = 1;
        else if (aZombiePreviewNum > aZombieNumInWave)
            aZombiePreviewNum = aZombieNumInWave;

        for (int i = 0; i < aZombiePreviewNum; i++)
            FindAndPlaceZombie((ZombieType)aZombieType, aZombieGrid);
    }
}

