// ==========================================================================
// CutScene::IsSurvivalRepick()
// @00177570  44 bytes
// ==========================================================================
bool CutScene::IsSurvivalRepick()
{
    if (!mApp->IsSurvivalMode())
        return false;

    // A repick happens when a survival level is restarted and the level-intro
    // cutscene is running again with at least one stage already cleared.
    return mBoard->mChallenge->mSurvivalStage > 0 && mApp->mGameScene == SCENE_LEVEL_INTRO;
}

// ==========================================================================
// CutScene::IsNonScrollingCutscene(void)
// @0017759C  104 bytes
// ==========================================================================
bool CutScene::IsNonScrollingCutscene()
{
    GameMode aGameMode = mApp->mGameMode;

    if (aGameMode == GAMEMODE_UPSELL || aGameMode == GAMEMODE_CHALLENGE_ICE || aGameMode == GAMEMODE_CHALLENGE_ZEN_GARDEN)
        return true;
    if (aGameMode == GAMEMODE_TREE_OF_WISDOM)
        return true;
    if (aGameMode == GAMEMODE_CHALLENGE_ZOMBIQUARIUM)
        return true;
    if (mApp->IsScaryPotterLevel())
        return true;
    if (mApp->IsIZombieLevel())
        return true;
    if (mApp->IsWhackAZombieLevel())
        return true;
    if (mApp->IsShovelLevel())
        return true;
    if (mApp->IsSquirrelLevel())
        return true;

    return mApp->IsWallnutBowlingLevel() != 0 || aGameMode == GAMEMODE_MP_VS_DEBUG || aGameMode == GAMEMODE_MP_VS;
}

// ==========================================================================
// CutScene::IsScrolledLeftAtStart(void)
// @00177604  74 bytes
// ==========================================================================
bool CutScene::IsScrolledLeftAtStart()
{
    if (mBoard->mChallenge->mSurvivalStage > 0 && mApp->IsSurvivalMode())
        return false;
    if (mApp->IsShovelLevel() || mApp->IsSquirrelLevel() || mApp->IsWallnutBowlingLevel())
        return false;

    return !IsNonScrollingCutscene();
}

// ==========================================================================
// CutScene::CanGetPacketUpgrade(void)
// @00177650  50 bytes
// ==========================================================================
bool CutScene::CanGetPacketUpgrade()
{
    int aCost = StoreScreen::GetItemCost(STORE_ITEM_PACKET_UPGRADE);
    if (mApp->mPlayerInfo->mPurchases[STORE_ITEM_PACKET_UPGRADE] != 0)
        return false;
    if (aCost > mApp->mPlayerInfo->mCoins)
        return false;

    return mApp->mPlayerInfo->mPacketUpgradeDeclines <= 1;
}

// ==========================================================================
// CutScene::CanGetSecondPacketUpgrade(void)
// @00177684  48 bytes
// ==========================================================================
bool CutScene::CanGetSecondPacketUpgrade()
{
    int aCost = StoreScreen::GetItemCost(STORE_ITEM_PACKET_UPGRADE);
    return mApp->mPlayerInfo->mPurchases[STORE_ITEM_PACKET_UPGRADE] == 1
        && aCost <= mApp->mPlayerInfo->mCoins
        && mApp->mPlayerInfo->mPacketUpgradeDeclines <= 1;
}

// ==========================================================================
// CutScene::StartSeedChooser(void)
// @001776B4  130 bytes
// ==========================================================================
void CutScene::StartSeedChooser()
{
    if (mBoard->StageHasRoof() && !IsSurvivalRepick())
        AddFlowerPots();

    mSeedChoosing = true;

    if (mApp->mSeedChooserScreen)
        mApp->mSeedChooserScreen->mMouseVisible = true;
    if (mApp->mZombieChooserScreen)
        mApp->mZombieChooserScreen->mMouseVisible = true;

    if (mApp->mVSSetupMenu)
    {
        mApp->mVSSetupMenu->mMouseVisible = true;
        if (mApp->mSeedChooserScreen)
            mApp->mWidgetManager->SetFocus(mApp->mSeedChooserScreen);
        else
            mApp->mWidgetManager->SetFocus(mApp->mVSSetupMenu);
    }
    else if (mApp->mSeedChooserScreen)
    {
        mApp->mWidgetManager->SetFocus(mApp->mSeedChooserScreen);
    }

    if (!mApp->IsCoopMode())
    {
        if (mApp->mGameMode == GAMEMODE_MP_VS)
            mApp->TryHelpTextScreen(2);
        return;
    }

    mApp->TryHelpTextScreen(3);
    if (mApp->mGameMode == GAMEMODE_MP_VS)
        mApp->TryHelpTextScreen(2);
}

// ==========================================================================
// CutScene::EndSeedChooser(void)
// @00177738  116 bytes
// ==========================================================================
void CutScene::EndSeedChooser()
{
    if (mApp->mSeedChooserScreen)
        mApp->mSeedChooserScreen->mMouseVisible = false;
    if (mApp->mZombieChooserScreen)
        mApp->mZombieChooserScreen->mMouseVisible = false;

    mSeedChoosing = false;
    mCutsceneTime = kTimeChooserUpEnd + mCrazyDaveTime + 10;
    if (IsNonScrollingCutscene())
        mCutsceneTime = mCrazyDaveTime + kTimePanLeft;

    mApp->mWidgetManager->SetFocus(mBoard);

    if (mApp->mGameMode == GAMEMODE_MP_VS)
    {
        mBoard->mChallenge->mSuddenDeathStartTick = Sexy::GetTickCount();
        mBoard->mEnableGraveStones = true;
    }
}

