// ==========================================================================
// CutScene::AdvanceCrazyDaveDialog(bool)
// @00178CD4  644 bytes
// ==========================================================================
void CutScene::AdvanceCrazyDaveDialog(bool theFromButton)
{
    if (mApp->mGameMode == GAMEMODE_UPSELL)
        return;

    int aMessage = mApp->mCrazyDaveMessageIndex;
    if (aMessage == -1)
        return;

    if (aMessage == 2406)
    {
        if (!theFromButton)
        {
            mBoard->SetTutorialState(TUTORIAL_SHOVEL_PICKUP);
            mApp->CrazyDaveLeave();
            return;
        }
    }
    else if (aMessage == 3200)
    {
        mApp->mPlayerInfo->mPurchases[28] = 1005; // STORE_ITEM_TREE_FOOD
    }

    if (!mApp->AdvanceCrazyDaveText())
    {
        mApp->CrazyDaveLeave();

        if (mApp->IsFinalBossLevel() && mApp->IsAdventureMode())
        {
            Reanimation *aReanim = mApp->ReanimationGet(mApp->mCrazyDaveReanimID);
            aReanim->PlayReanim("anim_grab", REANIM_PLAY_ONCE_AND_HOLD, 0, 18.0f);
            mApp->mMusic->FadeOut(50);
            if (!theFromButton)
                mApp->PlaySample(SOUND_BUNGEE_SCREAM, true);
        }
        else if (mApp->mGameMode == GAMEMODE_TREE_OF_WISDOM)
        {
            // Music2 hides MakeSureMusicIsPlaying with a wrong parameter list, so
            // the call goes through the Music base that owns the slot.
            Music *aMusic = mApp->mMusic;
            aMusic->MakeSureMusicIsPlaying(MUSIC_TUNE_ZEN_GARDEN); // MUSIC_TUNE_ZEN_GARDEN
        }
        else if (mBoard->ChooseSeedsOnCurrentLevel())
        {
            Music *aMusic = mApp->mMusic;
            aMusic->MakeSureMusicIsPlaying(MUSIC_TUNE_CHOOSE_YOUR_SEEDS); // MUSIC_TUNE_CHOOSE_YOUR_SEEDS
        }
        else if (IsNonScrollingCutscene())
        {
            mApp->mMusic->FadeOut(50);
        }
        return;
    }

    if (mApp->mCrazyDaveMessageIndex == 107 || mApp->mCrazyDaveMessageIndex == 2407)
        mBoard->mChallenge->ShovelAddWallnuts();

    if (mApp->mCrazyDaveMessageIndex == 405 || mApp->mCrazyDaveMessageIndex == 2411)
        mBoard->mChallenge->mShowBowlingLine = true;

    if (!theFromButton && (mApp->mCrazyDaveMessageIndex == 1503 || mApp->mCrazyDaveMessageIndex == 1553))
    {
        int aCost = StoreScreen::GetItemCost(STORE_ITEM_PACKET_UPGRADE); // STORE_ITEM_PACKET_UPGRADE
        Sexy::Dialog *aDialog = mApp->DoPacketPurchaseDialog(
            aCost, mApp->mPlayerInfo->mPurchases[21] + 7);
        mBoard->mCoinBankFadeCount = 100;
        aDialog->mX += 120;
        aDialog->mY += 130;

        if (aDialog->WaitForResult(true) == 1000)
        {
            mApp->mPlayerInfo->AddCoins(-aCost);
            mApp->mPlayerInfo->mPurchases[21]++;
            mApp->TryToSaveProfile();
            mBoard->mSeedBank[0]->UpdateWidth();
            if (mBoard->mSeedBank[1] != nullptr)
                mBoard->mSeedBank[1]->UpdateWidth();

            if (mApp->mCrazyDaveMessageIndex == 1503)
                mApp->CrazyDaveTalkIndex(1510);
            else if (mApp->mCrazyDaveMessageIndex == 1553)
                mApp->CrazyDaveTalkIndex(1560);
        }
        else
        {
            mApp->mPlayerInfo->mPacketUpgradeDeclines++;
            if (mApp->mCrazyDaveMessageIndex == 1503)
                mApp->CrazyDaveTalkIndex(1520);
            else if (mApp->mCrazyDaveMessageIndex == 1553)
                mApp->CrazyDaveTalkIndex(1570);
        }
    }

    if (mApp->mCrazyDaveMessageIndex == 406)
    {
        mBoard->mEnableGraveStones = true;
        AddGraveStoneParticles();
    }
}

