// ==========================================================================
// CutScene::ParseDelayTimeFromMessage(void)
// @00178FB0  250 bytes
// ==========================================================================
int CutScene::ParseDelayTimeFromMessage()
{
    Sexy::String aText = mApp->GetCrazyDaveText(mCrazyDaveLastTalkIndex);
    std::string aMessage = aText;

    size_t aStartPos = aMessage.find("{DELAY_");
    if (aStartPos == std::string::npos)
        return 100;

    size_t aEndPos = aMessage.find("}", aStartPos);
    mCrazyDaveCountDown = atoi(aMessage.substr(aStartPos + 7, aEndPos - aStartPos - 7).c_str());
    return mCrazyDaveCountDown;
}

// ==========================================================================
// CutScene::ParseTalkTimeFromMessage(void)
// @001790C0  250 bytes
// ==========================================================================
int CutScene::ParseTalkTimeFromMessage()
{
    Sexy::String aText = mApp->GetCrazyDaveText(mCrazyDaveLastTalkIndex);
    std::string aMessage = aText;

    size_t aStartPos = aMessage.find("{TIME_");
    if (aStartPos == std::string::npos)
        return 100;

    size_t aEndPos = aMessage.find("}", aStartPos);
    mCrazyDaveCountDown = atoi(aMessage.substr(aStartPos + 6, aEndPos - aStartPos - 6).c_str());
    return mCrazyDaveCountDown;
}

