// ==========================================================================
// CutScene::UpdateIntro(void)
// @0017B1B8  266 bytes
// ==========================================================================
void CutScene::UpdateIntro()
{
    int aOffsetX = TodAnimateCurve(kTimeLogoStart, kTimeLogoEnd, mCutsceneTime, -100, 100, 1);
    mBoard->Move(-aOffsetX, 0);

    if (mCutsceneTime == 10)
    {
        LoadIntroBoard();
    }

    if (mCutsceneTime == kTimeLogoFlash)
    {
        mApp->mMusic->FadeOut(250);
    }

    if (mCutsceneTime == kTimeLogoScaleEnd)
    {
        // 400000 is Board::MakeRenderOrder(RENDER_LAYER_TOP, 0, 0), which the
        // compiler folded into the call; 82 is the ParticleEffect.
        mApp->AddTodParticle(400.0f, 300.0f, 400000, ParticleEffect(82));
        mApp->mMuteSoundsForCutscene = false;
        mApp->PlaySample(SOUND_HUGE_WAVE, true);
        mApp->mMuteSoundsForCutscene = true;
    }

    if (mCutsceneTime == kTimeLogoFlash - 200)
    {
        mApp->mMuteSoundsForCutscene = false;
        mApp->PlaySample(SOUND_SIREN, true);
        mApp->mMuteSoundsForCutscene = true;
    }

    if (mCutsceneTime == kTimeLogoFinal)
        mApp->PreNewGame(GAMEMODE_ADVENTURE, false);
}

